using System;using System.Collections.ObjectModel;using System.Linq;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Input;using System.Windows.Threading;
namespace BF4Launcher;
public partial class MainWindow {
 readonly ObservableCollection<ModItem> modCards=new();ModItem? pressedCard;bool cardMoved,dragInProgress;
 void RefreshModCards(string? focusId=null){var wanted=repo.ModCards;var scroll=VisualChildren<ScrollViewer>(ModsList).FirstOrDefault();double offset=scroll?.VerticalOffset??0;for(int i=0;i<wanted.Count;i++){if(i<modCards.Count&&modCards[i]==wanted[i])continue;int from=modCards.IndexOf(wanted[i]);if(from>=0)modCards.Move(from,i);else modCards.Insert(i,wanted[i]);}while(modCards.Count>wanted.Count)modCards.RemoveAt(modCards.Count-1);if(focusId!=null)ModsList.SelectedItem=modCards.FirstOrDefault(m=>m.Manifest.Id==focusId);if(scroll!=null)Dispatcher.BeginInvoke(new Action(()=>scroll.ScrollToVerticalOffset(offset)),DispatcherPriority.Loaded);}
 void ToggleMod(ModItem item,bool enabled){if(!ready||busy)return;repo.SetModEnabled(item.Manifest.Id,enabled);backend.EnsureExternalMods();RefreshLabels();ShowNotice((enabled?"已启用：":"已停用：")+item.Name,enabled?"使用版本 "+item.Version+"；加载结果会在列表中更新。":"设置已保存；需要重启的补丁会在下次启动游戏时关闭。");}
 void ModToggle_Click(object sender,RoutedEventArgs e){if(Item(sender) is {} item)ToggleMod(item,item.Enabled);e.Handled=true;}
 void ModConfig_Click(object sender,RoutedEventArgs e){if(Item(sender) is {} item)Configure(item);e.Handled=true;}
 void Configure(ModItem item){var window=new ModVersionsWindow(repo,item,(key,action,body)=>backend.ModActionAsync(key,action,body),()=>{RefreshModCards(item.Manifest.Id);backend.EnsureExternalMods();RefreshLabels();},backend.StopModAsync,ex=>Log(ex.ToString())){Owner=this};if(window.ShowDialog()==true){RefreshModCards(item.Manifest.Id);RefreshLabels();ShowNotice(item.Name+"配置已保存","只修改了当前所选版本的参数。");}}
 void MoveCard(ModItem item,int target){int from=modCards.IndexOf(item);if(from<0||target<0||target>=modCards.Count){ShowNotice("已到列表边界",item.Name,false,true);return;}repo.MoveMod(item.Manifest.Id,target);RefreshModCards(item.Manifest.Id);RefreshLabels();ShowNotice("模组顺序已保存",item.Name+" 将按卡片顺序加载。");}
 void MoveUp_Click(object sender,RoutedEventArgs e){if(Item(sender) is {} item)MoveCard(item,modCards.IndexOf(item)-1);e.Handled=true;}
 void MoveDown_Click(object sender,RoutedEventArgs e){if(Item(sender) is {} item)MoveCard(item,modCards.IndexOf(item)+1);e.Handled=true;}
 async void RemoveMod_Click(object sender,RoutedEventArgs e){e.Handled=true;if(Item(sender) is not {} item)return;int count=repo.VersionsOf(item.Manifest.Id).Count;if(MessageBox.Show(this,"移除“"+item.Name+"”及其 "+count+" 个版本？文件和参数会保留在本地移除记录中。\n只卸载一个版本可进入模组设置操作。","移除模组",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;ModsList.IsEnabled=false;try{repo.SetModEnabled(item.Manifest.Id,false);await backend.StopModAsync(item);repo.RemoveModGroup(item.Manifest.Id);RefreshModCards();RefreshLabels();ShowNotice("已移除："+item.Name,"所有版本均已移入本地移除记录。");}catch(Exception ex){Log(ex.ToString());ShowNotice("模组未移除",ex.Message,true);}finally{ModsList.IsEnabled=true;}}
 static bool IsCardControl(DependencyObject? source)=>FindParent<ButtonBase>(source)!=null||FindParent<ScrollBar>(source)!=null||FindParent<Thumb>(source)!=null;
 void BeginCardPress(DependencyObject? source,MouseButton button,int clicks,Point position){dragStart=position;dragItem=pressedCard=null;cardMoved=false;if(button!=MouseButton.Left||clicks>1||IsCardControl(source))return;var row=FindParent<ListBoxItem>(source);if(row?.DataContext is not ModItem item)return;dragItem=item;bool handle=source is FrameworkElement f&&f.Name=="DragHandle";if(!handle)pressedCard=item;}
 bool TrackCardMotion(Point position){if((position-dragStart).Length<=7)return false;cardMoved=true;pressedCard=null;return true;}
 ModItem? EndCardPress(DependencyObject? source,MouseButton button){var item=pressedCard;pressedCard=null;dragItem=null;if(button!=MouseButton.Left||item==null||cardMoved||dragInProgress||IsCardControl(source))return null;var row=FindParent<ListBoxItem>(source);return row?.DataContext is ModItem same&&same.Manifest.Id==item.Manifest.Id?item:null;}
 void Mods_MouseDown(object sender,MouseButtonEventArgs e)=>BeginCardPress(e.OriginalSource as DependencyObject,e.ChangedButton,e.ClickCount,e.GetPosition(ModsList));
 void Mods_MouseMove(object sender,MouseEventArgs e){if(e.LeftButton!=MouseButtonState.Pressed||!TrackCardMotion(e.GetPosition(ModsList)))return;if(dragItem!=null&&!dragInProgress){var item=dragItem;dragItem=null;dragInProgress=true;try{DragDrop.DoDragDrop(ModsList,new DataObject(typeof(ModItem),item),DragDropEffects.Move);}finally{dragInProgress=false;pressedCard=null;}}}
 void Mods_MouseUp(object sender,MouseButtonEventArgs e){if(EndCardPress(e.OriginalSource as DependencyObject,e.ChangedButton) is {} item){ToggleMod(item,!item.Enabled);e.Handled=true;}}
 void Mods_DragOver(object sender,DragEventArgs e){e.Effects=e.Data.GetDataPresent(DataFormats.FileDrop)?DragDropEffects.Copy:e.Data.GetDataPresent(typeof(ModItem))?DragDropEffects.Move:DragDropEffects.None;e.Handled=true;}
 void Mods_Drop(object sender,DragEventArgs e){e.Handled=true;pressedCard=null;cardMoved=true;if(e.Data.GetDataPresent(DataFormats.FileDrop)){ImportFiles(((string[])e.Data.GetData(DataFormats.FileDrop)).Where(p=>p.EndsWith(".zip",StringComparison.OrdinalIgnoreCase)||p.EndsWith(".bf4mod",StringComparison.OrdinalIgnoreCase)));return;}if(e.Data.GetData(typeof(ModItem)) is ModItem item){var target=FindParent<ListBoxItem>(e.OriginalSource as DependencyObject)?.DataContext as ModItem;int to=target==null?modCards.Count-1:modCards.IndexOf(target);if(to>=0&&modCards.IndexOf(item)!=to)MoveCard(item,to);}}
}
